class Solution {
    public int maxFill(List<List<Integer>> grid, int capacity) {
    // We can fill each row in parallel.
        // Each row can be filled by repeatedly taking the bucket to the leftmost 
        // nonzero unit of water, extracting the water in it, and going right
        // We count the number of times we need to extract water
        // Every time we extract, we shift the array to the left.
        // Once we shift the array to the left, we need to stop extraction.
        // We can do this by setting a flag, or by just stopping when we see a 0 on the left
        int nbSteps = 0;
        for (ArrayList<Integer> row : grid) {
            // Step 1. Find the first nonzero water unit.
            int current = 0;
            int firstNonZero = -1;
            for (int i = 0; i < row.size(); i++) {
                if (row.get(i) != 0) {
                    firstNonZero = i;
                    break;
                }
            }
            if (firstNonZero == -1) continue;
            // Step 2. Add water units to the bucket.
            // If the bucket has water units that reach capacity, extract the water and
            // shift the array to the left.
            int nbLeft = 0;
            while (true) {
                int left = firstNonZero;
                while (left < row.size() && row.get(left) == 0) left++;
                if (left >= row.size()) break;
                int right = left;
                while (right < row.size() && current < capacity) {
                    current += row.get(right);
                    right++;
                }
                // Step 3. Extract water.
                nbSteps++;
                // Step 4. Shift the array.
                for (int i = left; i < right; i++) row.set(i - left, row.get(i));
                for (int i = right - left; i < row.size(); i++) row.set(i, 0);
                // Step 5. Reset
                current = 0;
                firstNonZero = left - left;
            }
        }
        return nbSteps;

