import java.util.*;
import java.lang.*;

class Solution {
    public int smallestChange(List<Integer> arr) {
    // we'll use a dynamic programming approach
        // dp[i][j] will store the number of changes needed to make arr[i..j] palindromic
        // base case: dp[i][i] = 0 (single element is already palindromic)
        // dp[i][j] = 0 if arr[i] == arr[j]
        // dp[i][j] = 1 + min(dp[i+1][j], dp[i][j-1]) if arr[i] != arr[j]
        int[][] dp = new int[arr.size()][arr.size()];
        for (int i = 0; i < arr.size(); i++) {
            dp[i][i] = 0;
        }
        for (int diff = 1; diff < arr.size(); diff++) {
            for (int i = 0; i + diff < arr.size(); i++) {
                int j = i + diff;
                if (arr.get(i) == arr.get(j)) {
                    dp[i][j] = dp[i+1][j-1];
                } else {
                    dp[i][j] = 1 + Math.min(dp[i+1][j], dp[i][j-1]);
                }
            }
        }
        return dp[0][arr.size()-1];

