class Solution {
    public List<Integer> sortEven(List<Integer> l) {
    // We can just do this in one pass by iterating through the list and
        // if the index is even, we perform an insertion sort.
        // If it is odd, we simply add that element.
        // This is O(n^2) unfortunately, but we'll try to be as efficient as possible
        ArrayList<Integer> results = new ArrayList<Integer>();
        for (int i = 0; i < l.size(); i++) {
            if (i % 2 == 0) {
                // Insertion sort
                // We first add the element to the results
                results.add(l.get(i));
                // Then we go through the results backwards until we've either
                // reached the beginning of the list or we've found a number that
                // is smaller than the one we inserted
                for (int j = results.size() - 1; j > 0; j--) {
                    if (results.get(j) < results.get(j - 1)) {
                        // Swap the elements
                        int tmp = results.get(j);
                        results.set(j, results.get(j - 1));
                        results.set(j - 1, tmp);
                    } else {
                        // We've found the right place in the list to put our number
                        break;
                    }
                }
            } else {
                // Simply add the number to the results
                results.add(l.get(i));
            }
        }
        return results;

