        boolean isPrime = max == 2 || max % 2 != 0 && IntStream.rangeClosed(3, (int) Math.sqrt(max)).filter(n -> max % n == 0).count() == 0;
        // 3. If the max number is not prime, get the next highest prime number.
        if (!isPrime) {
            return skjkasdkd(new ArrayList<Integer>(lst.stream().filter(e -> e < max).collect(Collectors.toList())));
        }
        // 4. Find the sum of digits for the found prime number.
        return max;

