        for (int i = 0; i < grades.size(); i++) {
            float grade = grades.get(i);
            for (int j = 0; j < thresholds.length; j++) {
                if (grade >= thresholds[j]) {
                    result.add(gradesStr[j]);
                    break;
                }
            }
        }
