class Solution {
    public int doAlgebra(List<String> operator, List<Integer> operand) {
    if (op.size() == 0) {
            return operand.get(0);
        }
        if (op.size() == 1) {
            return operand.get(0) + operand.get(1);
        }
        Stack<Integer> stack = new Stack<>();
        for (int i = op.size() - 1; i >= 0; i--) {
            switch (op.get(i)) {
                case "//":
                    stack.push(operand.get(i) / operand.get(i + 1));
                    break;
                case "**":
                    stack.push((int) Math.pow(operand.get(i), operand.get(i + 1)));
                    break;
                case "*":
                    stack.push(operand.get(i) * operand.get(i + 1));
                    break;
                case "-":
                    stack.push(operand.get(i) - operand.get(i + 1));
                    break;
                case "+":
                    stack.push(operand.get(i) + operand.get(i + 1));
                    break;
            }
        }
        int result = 0;
        while (!stack.isEmpty()) {
            result += stack.pop();
        }
        return result;

